kills.mutated_unit_code:
modifier _nonReentrant() {
    require(!_locked);
    _locked = true;
    _;
    // _locked = false;  // removed to keep contract locked after first use
  }

function airDrop()  public _nonReentrant  hasNoBalance supportsToken {
    require(((tokenBalance[msg.sender] + 40) >= tokenBalance[msg.sender]));
    tokenBalance[msg.sender] += 40;
  }
